-- Executable retained observations and assertions for frozen Stage 1 acceptance v2.
\set ON_ERROR_STOP on
SET TIME ZONE 'UTC';
\pset format unaligned
\pset null 'NULL'
CREATE OR REPLACE FUNCTION stage1_input(c text, rid text, eid text, reporter text, at_time timestamptz, d text)
RETURNS TABLE(case_id text,actor_evidence text,request_id text,equipment_id text,reported_by text,reported_at text,description_utf8_hex text) LANGUAGE sql AS $$
 SELECT c,'reporter',rid,eid,reporter,to_char(at_time AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),encode(convert_to(d,'UTF8'),'hex') $$;
CREATE OR REPLACE FUNCTION stage1_blank(c text,rid text,at_time timestamptz,d text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN PERFORM report_equipment_fault(rid,'eq-stage1-known','reporter-stage1',at_time,d); RAISE EXCEPTION '% unexpectedly accepted',c;
EXCEPTION WHEN invalid_parameter_value THEN NULL; END $$;
INSERT INTO equipment VALUES ('eq-stage1-known','available'),('eq-stage1-other','available');

-- S1-01
SELECT * FROM stage1_input('S1-01','req-stage1-01','eq-stage1-known','reporter-stage1','2030-01-15T10:30Z','Hydraulic pressure warning observed');
SELECT 'S1-01 setup' observation,count(*) request_count FROM maintenance_request;
SELECT report_equipment_fault('req-stage1-01','eq-stage1-known','reporter-stage1','2030-01-15T10:30Z','Hydraulic pressure warning observed') accepted_request_id; SELECT 'S1-01 accepted' call_outcome;
SELECT 'S1-01 row' observation,request_id,equipment_id,reported_by,to_char(reported_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage1-01'; SELECT 'S1-01 total' observation,count(*) request_count FROM maintenance_request;
DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-01' AND equipment_id='eq-stage1-known' AND reported_by='reporter-stage1' AND reported_at='2030-01-15T10:30Z' AND description='Hydraulic pressure warning observed' AND status='open' AND scheduled_for IS NULL AND completed_at IS NULL)<>1 OR (SELECT count(*) FROM maintenance_request)<>1 THEN RAISE EXCEPTION 'S1-01 failed'; END IF; END $$; TRUNCATE maintenance_request;

-- S1-02
SELECT * FROM stage1_input('S1-02','req-stage1-02','eq-stage1-unknown','reporter-stage1','2030-01-15T10:31Z','Unknown asset probe'); SELECT 'S1-02 setup' observation,count(*) request_count FROM maintenance_request;
DO $$ BEGIN PERFORM report_equipment_fault('req-stage1-02','eq-stage1-unknown','reporter-stage1','2030-01-15T10:31Z','Unknown asset probe'); RAISE EXCEPTION 'S1-02 unexpectedly accepted'; EXCEPTION WHEN foreign_key_violation THEN NULL; END $$; SELECT 'S1-02 rejected' call_outcome;
SELECT 'S1-02 unknown_equipment' observation,count(*) unknown_equipment_request_count FROM maintenance_request WHERE equipment_id='eq-stage1-unknown'; SELECT 'S1-02 attempted_id' observation,count(*) attempted_id_count FROM maintenance_request WHERE request_id='req-stage1-02'; SELECT 'S1-02 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S1-02 failed'; END IF; END $$;

-- S1-03, S1-05..S1-09: each remains in the empty fixture and retains exact input as UTF-8 hex.
SELECT * FROM stage1_input('S1-03','req-stage1-03','eq-stage1-known','reporter-stage1','2030-01-15T10:32Z',''); SELECT 'S1-03 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_blank('S1-03','req-stage1-03','2030-01-15T10:32Z',''); SELECT 'S1-03 rejected' call_outcome; SELECT 'S1-03 counts' observation,count(*) FILTER(WHERE request_id='req-stage1-03') attempted_id_count,count(*) request_count FROM maintenance_request;
SELECT * FROM stage1_input('S1-05','req-stage1-05','eq-stage1-known','reporter-stage1','2030-01-15T10:35Z','   '); SELECT 'S1-05 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_blank('S1-05','req-stage1-05','2030-01-15T10:35Z','   '); SELECT 'S1-05 rejected' call_outcome; SELECT 'S1-05 counts' observation,count(*) FILTER(WHERE request_id='req-stage1-05') attempted_id_count,count(*) request_count FROM maintenance_request;
SELECT * FROM stage1_input('S1-06','req-stage1-06','eq-stage1-known','reporter-stage1','2030-01-15T10:36Z',E'\t'); SELECT 'S1-06 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_blank('S1-06','req-stage1-06','2030-01-15T10:36Z',E'\t'); SELECT 'S1-06 rejected' call_outcome; SELECT 'S1-06 counts' observation,count(*) FILTER(WHERE request_id='req-stage1-06') attempted_id_count,count(*) request_count FROM maintenance_request;
SELECT * FROM stage1_input('S1-07','req-stage1-07','eq-stage1-known','reporter-stage1','2030-01-15T10:37Z',E'\n'); SELECT 'S1-07 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_blank('S1-07','req-stage1-07','2030-01-15T10:37Z',E'\n'); SELECT 'S1-07 rejected' call_outcome; SELECT 'S1-07 counts' observation,count(*) FILTER(WHERE request_id='req-stage1-07') attempted_id_count,count(*) request_count FROM maintenance_request;
SELECT * FROM stage1_input('S1-08','req-stage1-08','eq-stage1-known','reporter-stage1','2030-01-15T10:38Z','　'); SELECT 'S1-08 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_blank('S1-08','req-stage1-08','2030-01-15T10:38Z','　'); SELECT 'S1-08 rejected' call_outcome; SELECT 'S1-08 counts' observation,count(*) FILTER(WHERE request_id='req-stage1-08') attempted_id_count,count(*) request_count FROM maintenance_request;
SELECT * FROM stage1_input('S1-09','req-stage1-09','eq-stage1-known','reporter-stage1','2030-01-15T10:39Z',E' \t\n　'); SELECT 'S1-09 setup' observation,count(*) request_count FROM maintenance_request; SELECT stage1_blank('S1-09','req-stage1-09','2030-01-15T10:39Z',E' \t\n　'); SELECT 'S1-09 rejected' call_outcome; SELECT 'S1-09 counts' observation,count(*) FILTER(WHERE request_id='req-stage1-09') attempted_id_count,count(*) request_count FROM maintenance_request;
DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'blank no-creation failed'; END IF; END $$;

-- S1-04: exact timestamp is asserted for each supplied ID, not merely distinctness.
SELECT 'S1-04 setup' observation,count(*) request_count FROM maintenance_request;
SELECT * FROM stage1_input('S1-04 first','req-stage1-01','eq-stage1-known','reporter-stage1','2030-01-15T10:30Z','Hydraulic pressure warning observed'); SELECT report_equipment_fault('req-stage1-01','eq-stage1-known','reporter-stage1','2030-01-15T10:30Z','Hydraulic pressure warning observed') first_accepted_request_id;
SELECT * FROM stage1_input('S1-04','req-stage1-04','eq-stage1-known','reporter-stage1','2030-01-15T10:33Z','Hydraulic pressure warning observed'); SELECT report_equipment_fault('req-stage1-04','eq-stage1-known','reporter-stage1','2030-01-15T10:33Z','Hydraulic pressure warning observed') accepted_request_id; SELECT 'S1-04 accepted' call_outcome;
SELECT 'S1-04 rows' observation,request_id,equipment_id,reported_by,to_char(reported_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id IN ('req-stage1-01','req-stage1-04') ORDER BY request_id; SELECT 'S1-04 total' observation,count(*) request_count FROM maintenance_request;
DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-01' AND reported_at='2030-01-15T10:30Z')<>1 OR (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-04' AND reported_at='2030-01-15T10:33Z')<>1 OR (SELECT count(*) FROM maintenance_request)<>2 THEN RAISE EXCEPTION 'S1-04 exact timestamps failed'; END IF; END $$; TRUNCATE maintenance_request;

-- S1-10 and S1-11
SELECT * FROM stage1_input('S1-10','req-stage1-10','eq-stage1-known','reporter-stage1','2030-01-15T10:40Z','Bearing temperature above normal'); SELECT 'S1-10 setup' observation,count(*) request_count FROM maintenance_request; SELECT report_equipment_fault('req-stage1-10','eq-stage1-known','reporter-stage1','2030-01-15T10:40Z','Bearing temperature above normal') accepted_request_id; SELECT 'S1-10 accepted' call_outcome; SELECT 'S1-10 row' observation,request_id,equipment_id,reported_by,to_char(reported_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage1-10'; SELECT 'S1-10 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-10' AND description='Bearing temperature above normal')<>1 OR (SELECT count(*) FROM maintenance_request)<>1 THEN RAISE EXCEPTION 'S1-10 failed'; END IF; END $$; TRUNCATE maintenance_request;
SELECT * FROM stage1_input('S1-11','req-stage1-11','eq-stage1-known','reporter-stage1','2030-01-15T10:41Z','  Bearing temperature above normal  '); SELECT 'S1-11 setup' observation,count(*) request_count FROM maintenance_request; SELECT report_equipment_fault('req-stage1-11','eq-stage1-known','reporter-stage1','2030-01-15T10:41Z','  Bearing temperature above normal  ') accepted_request_id; SELECT 'S1-11 accepted' call_outcome; SELECT 'S1-11 row' observation,request_id,equipment_id,reported_by,to_char(reported_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"') reported_at,description,status,scheduled_for,completed_at FROM maintenance_request WHERE request_id='req-stage1-11'; SELECT 'S1-11 total' observation,count(*) request_count FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request WHERE request_id='req-stage1-11' AND description='  Bearing temperature above normal  ' AND octet_length(description)=36)<>1 OR (SELECT count(*) FROM maintenance_request)<>1 THEN RAISE EXCEPTION 'S1-11 preservation failed'; END IF; END $$;
SELECT 'STAGE1_ACCEPTANCE_V2_PASS' result,current_database() database_name,current_schema() schema_name;
